import {dayKey,uid,pointsFor,balance,earned,completeTask,claimReward,streak,createState,validateState} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13"/><path d="M12 8H8a3 3 0 1 1 3-3l1 3Zm0 0h4a3 3 0 1 0-3-3l-1 3Z"/>',chart:'<path d="M4 19V5m0 14h16M8 15v-4m5 4V7m5 8V9"/>',settings:'<path d="M9 3h6l1 3 3 1 1 5-2 2v4l-5 3-3-2-4-1-2-5 2-3V6Z"/><circle cx="12" cy="12" r="3"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 5h2m4 0h2"/>',check:'<path d="m5 12 4 4L19 6"/>',circlecheck:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',flame:'<path d="M12 2c4 7 8 8 8 13a8 8 0 0 1-16 0c0-4 2-6 4-8 0 4 2 5 3 4 2-2 1-6 1-9Z"/>',sparkle:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',heart:'<path d="M12 20 4 12a5 5 0 0 1 8-6 5 5 0 0 1 8 6Z"/>',play:'<path d="m9 5 11 7-11 7Z"/>',leaf:'<path d="M20 3C7 2 1 12 7 17S22 14 20 3ZM5 21l10-11"/>',cloud:'<path d="M6 19a5 5 0 1 1 1-10 7 7 0 0 1 13 3 4 4 0 0 1-1 7Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.sparkle}</svg>`;
let state;try{state=validateState(JSON.parse(localStorage.getItem('bloom-state')));}catch{state=createState();}
let page=['today','rewards','insights','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'today',filter='all',deferredInstall=null,cloud=null,cloudStatus='Device mode',cloudError='',syncTimer,cloudBusy=false,unsynced=localStorage.getItem('bloom-dirty')==='true',lastDay=dayKey(),timer={duration:25*60,remaining:25*60,running:false,end:0,taskId:null};
const names={today:'Today',rewards:'My rewards',insights:'My growth',settings:'Settings'},navIcons={today:'sun',rewards:'gift',insights:'chart',settings:'settings'};
function save({sync=true}={}){try{localStorage.setItem('bloom-state',JSON.stringify(state));if(sync){unsynced=true;localStorage.setItem('bloom-dirty','true');queueSync();}}catch{toast('Your device storage is full. Export a backup in Settings.');}}
function queueSync(){if(!cloud?.user)return;clearTimeout(syncTimer);syncTimer=setTimeout(async()=>{cloudBusy=true;setCloudStatus('Saving…');try{await cloud.saveState(state);unsynced=false;localStorage.setItem('bloom-dirty','false');setCloudStatus('Synced');}catch{setCloudStatus('Sync paused');toast('Cloud sync paused. Your changes are saved on this device.');}finally{cloudBusy=false;}},800);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const colors=['#99b47f','#dac79d','#d8a385','#b6c1d3'];$('#confetti').innerHTML=Array.from({length:35},(_,i)=>`<i class="confetti-piece" style="left:${25+Math.random()*50}%;top:${Math.random()*15}%;background:${colors[i%4]};animation-delay:${Math.random()*.3}s;transform:rotate(${Math.random()*180}deg)"></i>`).join('');setTimeout(()=>$('#confetti').innerHTML='',2000);}
function todayTasks(){return state.tasks.filter(t=>t.date===dayKey());}
function render(){const tasks=todayTasks();$('#navigation').innerHTML=Object.keys(names).map(p=>`<a href="#${p}" class="nav-link ${p===page?'active':''}" ${p===page?'aria-current="page"':''}>${icon(navIcons[p])}${names[p]}${p==='today'?`<span class="nav-count">${tasks.filter(t=>!t.done).length}</span>`:''}</a>`).join('');$('#page-crumb').innerHTML=`My workspace <span>/</span> ${names[page]}`;$('#notification-button').innerHTML=icon('bell');$('#install-side').innerHTML=icon('download')+'<span>Install Bloom app</span>';$('#profile-name').textContent=state.settings.name||'Your little corner';document.querySelectorAll('.avatar').forEach(a=>a.textContent=(state.settings.name||'You')[0].toUpperCase());$('#sync-label').textContent=cloudStatus;$('#storage-status').textContent=cloud?.user?cloud.user.email:'Saved on this device';$('#content').innerHTML=`<div class="view-enter">${({today:renderToday,rewards:renderRewards,insights:renderInsights,settings:renderSettings}[page])()}</div>`;document.title=`${names[page]} · Bloom`;}
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subheading">${sub}</p></div>${action}</div>`;}
const plant=`<div class="hero-flower">✳</div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 260 190"><ellipse cx="144" cy="180" rx="75" ry="8" fill="#d7e1cd"/><path d="M143 156q0-70 13-109" stroke="#8ca176" stroke-width="3" fill="none"/><path d="M149 106c-48 1-66-30-62-49 40 0 63 19 62 49" fill="#9caf89"/><path d="M151 85c43 1 61-25 58-47-37 0-60 20-58 47" fill="#afbd98"/><path d="M146 137c-36 1-51-22-47-40 30 0 48 17 47 40" fill="#bbcaab"/><path d="M151 124c35 2 53-18 51-35-32-1-50 13-51 35" fill="#839b73"/><path d="M157 59c-19-18-13-40 1-50 22 20 16 38-1 50" fill="#879f77"/><path d="M115 145h67l-9 35h-49Z" fill="#c9b89b"/><rect x="111" y="142" width="75" height="9" rx="3" fill="#d7c8ae"/><path d="m53 111 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z" fill="#c6ceae"/><circle cx="215" cy="117" r="3" fill="#b8c7a5"/><path d="M68 170h22" stroke="#c5ceb7" stroke-width="2"/><circle cx="64" cy="170" r="2" fill="#b8c7a5"/></svg></div>`;
function stat(iconName,label,value,unit){return `<div class="stat"><span class="stat-icon">${icon(iconName)}</span><div><div class="stat-title">${label}</div><div class="stat-value">${value}<small>${unit}</small></div></div></div>`;}
function weekDays(){const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{let day=new Date(d);day.setDate(d.getDate()+i);return day;});}
function renderToday(){const tasks=todayTasks(),done=tasks.filter(t=>t.done).length,pct=tasks.length?Math.round(done/tasks.length*100):0;const rewards=[...state.rewards].sort((a,b)=>a.cost-b.cost),next=rewards.find(r=>r.cost>balance(state))||rewards[0];const displayed=tasks.filter(t=>filter==='all'||(filter==='done'?t.done:!t.done));const date=new Date().toLocaleDateString('en',{weekday:'short',month:'short',day:'numeric'});return heading('A FRESH CHANCE TO GROW',`Make room for a good day<span class="wave">☀️</span>`,state.settings.name?`Hey ${esc(state.settings.name)}, let's take it one small step at a time.`:'You don’t need to do it all. Just start with one small thing.',`<div class="date-pill">${icon('calendar')}${esc(date)}</div>`)+`<section class="hero"><div class="hero-copy"><div class="hero-kicker">${icon('leaf')} A LITTLE ENCOURAGEMENT</div><h2>You don’t have to be perfect.<br>Just keep showing up.</h2><p>Small steps today become the life you want tomorrow.</p></div>${plant}</section><div class="stats-grid">${stat('circlecheck','Today’s progress',`${done}<small>/ ${tasks.length}</small>`,'tasks completed')}${stat('flame','Your consistency',streak(state),'day streak')}${stat('sparkle','Reward balance',balance(state),'points to enjoy')}</div><div class="dashboard-grid"><section><div class="section-head"><div><h2>Your little wins today <span style="color:#a1ad94;font-size:12px">${tasks.length}</span></h2><p>A plan that makes space for you.</p></div><button class="primary" data-action="add-task">${icon('plus')} Add task</button></div><div class="filter-row" role="group" aria-label="Filter tasks">${[['all','All tasks',tasks.length],['pending','To do',tasks.length-done],['done','Completed',done]].map(([v,l,n])=>`<button class="filter-button ${filter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${filter===v}">${l}<span>${n}</span></button>`).join('')}</div>${state.starter&&tasks.length?'<p class="onboarding-hint">A few starter ideas for your first day. Edit them to make this plan yours.</p>':''}<div class="task-list">${displayed.length?displayed.map(taskCard).join(''):`<div class="empty">${icon('leaf')}<h3>${filter==='done'?'Your first win is waiting':filter==='pending'&&tasks.length?'You showed up for yourself.':'A little space for possibility.'}</h3><p>${filter==='done'?'Complete a task and celebrate it here.':filter==='pending'&&tasks.length?'Enjoy a well-earned pause. You did enough today.':'Add one small thing you’d like to do today.'}</p></div>`}</div><button class="quick-add" data-action="add-task">${icon('plus')} What’s one more small thing you’d like to do?</button>${!tasks.length&&state.tasks.some(t=>!t.done&&t.date<dayKey())?'<button class="text-button" data-action="carry">Bring unfinished tasks into today →</button>':''}<p class="kind-note">${icon('heart')} A smaller list you finish feels better than a perfect list you avoid.</p><div class="focus-teaser"><span class="stat-icon">${icon('clock')}</span><div><h3>A little focus goes a long way.</h3><p>One thing. A few quiet minutes. You’ve got this.</p></div><button class="secondary" data-action="focus">${icon('play')} ${timer.running?'Open timer':'Let’s focus'}</button></div></section><aside class="right-column"><section class="panel"><h2 class="panel-title">${icon('sun')} Today, you’re growing</h2><div class="progress-ring"><svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="59"/><circle class="fill" cx="70" cy="70" r="59" stroke-dasharray="370.7" stroke-dashoffset="${370.7*(1-pct/100)}"/></svg><div class="ring-text"><strong>${pct}%</strong><small>of your daily intentions</small></div></div><p class="progress-caption">${pct===100&&tasks.length?'Look at you. You did it!':done?'Every little win counts.':'Every beginning is a little win.'}</p><p>${done?`${done} promise${done===1?'':'s'} kept to yourself today.`:'Your first small step is all it takes.'}</p><div class="divider"></div><div class="mini-week">${weekDays().map(d=>{const key=dayKey(d),completed=state.tasks.some(t=>t.done&&dayKey(new Date(t.completedAt))===key);return `<div class="mini-day"><span>${d.toLocaleDateString('en',{weekday:'narrow'})}</span><span class="day-dot ${key===dayKey()?'today':''} ${completed?'complete':''}" title="${key}: ${completed?'progress made':'no completions'}">${completed?'✓':d.getDate()}</span></div>`;}).join('')}</div></section><section class="panel reward-preview"><h2 class="panel-title">${icon('gift')} A little joy to work toward</h2>${next?`<span class="reward-emoji">${esc(next.emoji)}</span><h3>${esc(next.title)}</h3><p>A small reward. A lovely reason to start.</p><div class="reward-track"><span style="width:${Math.min(balance(state)/next.cost*100,100)}%"></span></div><div class="reward-track-caption"><span>${balance(state)} / ${next.cost} points</span><span>${balance(state)>=next.cost?'Ready to enjoy!':`${next.cost-balance(state)} to go`}</span></div><button class="text-button" data-action="goto" data-value="rewards">Make your rewards yours ${icon('arrow')}</button>`:'<p>Add a reward that feels like you.</p><button class="text-button" data-action="add-reward">Create your first reward →</button>'}</section></aside></div>`;}
function taskCard(t){return `<article class="task-card ${t.done?'done':''}"><button class="check-task" data-action="complete" data-id="${esc(t.id)}" aria-label="${t.done?'Undo':'Complete'} ${esc(t.title)}" aria-pressed="${t.done}">${t.done?icon('check'):''}</button><div class="task-body"><h3 class="task-title">${esc(t.title)}</h3><div class="task-meta"><span class="tag ${['Work','Personal'].includes(t.category)?t.category.toLowerCase():''}">${esc(t.category)}</span><span>${icon('clock')}${t.minutes} min</span>${t.reminder?`<span>${icon('bell')}${esc(t.reminder)}</span>`:''}${!t.done?`<button class="text-button" style="font-size:9px;padding:0" data-action="focus" data-id="${esc(t.id)}">Start small ${icon('arrow')}</button>`:''}</div>${t.reward?`<div class="task-reward">${icon('gift')}${t.done?'Unlocked: ':''}${esc(t.reward)}</div>`:''}</div><div class="task-actions"><span class="points">+${t.points} pts</span><button class="more-button" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Edit ${esc(t.title)}">${icon('dots')}</button></div></article>`;}
function renderRewards(){return heading('A LITTLE JOY, WELL EARNED','Good things to look forward to','You choose the treats. Your little wins unlock them.',`<div class="view-title-actions"><button class="primary" data-action="add-reward">${icon('plus')} Add reward</button></div>`)+`<div class="balance-banner">${icon('sparkle')}<div><h2>${balance(state)} little points of possibility</h2><p>Earn 20–60 points for each task you complete.</p></div></div><div class="view-grid">${state.rewards.map(r=>`<article class="panel reward-card"><button class="more-button" data-action="edit-reward" data-id="${esc(r.id)}" aria-label="Edit ${esc(r.title)}">${icon('dots')}</button><span class="reward-emoji">${esc(r.emoji)}</span><h3>${esc(r.title)}</h3><p>${r.cost} points · ${balance(state)>=r.cost?'Yours to enjoy':`${r.cost-balance(state)} more to unlock`}</p><button class="${balance(state)>=r.cost?'primary':'secondary'}" data-action="claim" data-id="${esc(r.id)}" ${balance(state)<r.cost?'disabled':''}>${icon('gift')} ${balance(state)>=r.cost?'Enjoy this reward':'Keep growing'}</button></article>`).join('')}</div>${!state.rewards.length?`<div class="empty">${icon('gift')}<h3>What makes you smile?</h3><p>Add a reward to give your next little win something to look forward to.</p></div>`:''}<section class="panel wide-panel"><h2 class="panel-title">${icon('heart')} Moments you’ve earned</h2>${state.claims.length?[...state.claims].reverse().slice(0,15).map(c=>`<div class="history-row"><span class="history-emoji">${esc(c.emoji)}</span><div>${esc(c.title)}<small>${new Date(c.claimedAt).toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'})}</small></div><span>−${c.cost} pts</span></div>`).join(''):'<p class="soft-text" style="margin-top:15px">Your reward story starts with one small step. Your claimed rewards will live here.</p>'}</section>`;}
function renderInsights(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d;}),counts=days.map(d=>state.tasks.filter(t=>t.done&&dayKey(new Date(t.completedAt))===dayKey(d)).length),max=Math.max(5,...counts),total=state.tasks.filter(t=>t.done).length;return heading('LOOK HOW FAR YOU’VE COME','Progress, at your own pace','Every small step leaves a little evidence that you can.')+`<div class="stats-grid">${stat('circlecheck','Promises kept',total,'tasks, all time')}${stat('flame','Showing up',streak(state),'day streak')}${stat('clock','Space for focus',state.focusSessions.reduce((n,s)=>n+s.minutes,0),'minutes, all time')}</div><div class="settings-grid"><section class="panel"><div class="section-head"><h2>Your last seven days</h2><span class="soft-text">Tasks completed</span></div><div class="chart" role="img" aria-label="${days.map((d,i)=>`${d.toLocaleDateString('en',{weekday:'short'})}: ${counts[i]} tasks`).join(', ')}">${days.map((d,i)=>`<div class="chart-column"><strong>${counts[i]}</strong><div class="chart-bar" style="height:${Math.max(2,counts[i]/max*130)}px;${dayKey(d)===dayKey()?'background:#739365':''}"></div><span>${d.toLocaleDateString('en',{weekday:'short'})}</span></div>`).join('')}</div><div class="insight-note">${total?'You’re building trust with yourself, one kept promise at a time.':'A fresh start looks good on you. Complete one small task to plant your first seed.'}</div></section><section class="panel"><h2 class="panel-title">${icon('leaf')} Your progress, in perspective</h2><div class="setting-row"><div><strong>${earned(state)} points earned</strong><small>Every one started with showing up.</small></div>${icon('sparkle')}</div><div class="setting-row"><div><strong>${state.claims.length} rewards enjoyed</strong><small>Rest and joy are part of the process.</small></div>${icon('gift')}</div><div class="setting-row"><div><strong>${state.focusSessions.length} focus sessions</strong><small>Time you made for what matters.</small></div>${icon('clock')}</div><p class="soft-text" style="margin-top:25px">A streak grows when you complete at least one task a day. Missing a day is a chance to begin again.</p></section></div>`;}
function renderSettings(){return heading('MAKE YOURSELF AT HOME','A space that feels like you','A few thoughtful settings. A little less friction.')+`<div class="settings-grid"><section class="panel"><h2>Your little corner</h2><p>Let’s make your daily encouragement personal.</p><form id="profile-form"><label class="field"><span>What should we call you?</span><input name="name" value="${esc(state.settings.name)}" maxlength="40" placeholder="Your first name" autocomplete="given-name"></label><div class="form-actions"><button class="primary" type="submit">Save your name</button></div></form><div class="setting-row"><div><strong>Take Bloom with you</strong><small>Install it on your home screen for a quieter, app-like experience.</small></div><button class="secondary" data-action="install">${icon('download')} Install</button></div></section><section class="panel"><h2>A gentle nudge</h2><p>Encouragement when you want it. Always your choice.</p><div class="setting-row"><div><strong>Device notifications</strong><small>${state.settings.notifications?'Enabled for this browser.':'Allow a little reminder to return to your intentions.'}</small></div><button class="toggle ${state.settings.notifications?'on':''}" data-action="notifications" role="switch" aria-checked="${state.settings.notifications}" aria-label="Device notifications"></button></div><div class="setting-row"><div><strong>Try a little encouragement</strong><small>Send yourself a test notification.</small></div><button class="secondary" data-action="test-notification">Test</button></div><p class="soft-text" style="margin-top:20px">Task reminders work while Bloom is open. Notifications when the app is closed need Firebase Cloud Messaging and the scheduled backend.</p></section><section class="panel"><span class="status-chip ${cloud?.user?'':'warning-chip'}">${icon('cloud')} ${cloud?.user?'Firebase connected':'Firebase · ready to connect'}</span><h2>Keep your growth in sync</h2><p>${cloud?.user?`Signed in as ${esc(cloud.user.email)}. Your data syncs across your signed-in devices.`:'Connect your Firebase project to enable secure sign-in and cloud storage. Your data currently stays on this device.'}</p>${cloudError?`<p class="error-message">${esc(cloudError)}</p>`:''}<div class="account-actions"><button class="${cloud?.user?'secondary':'primary'}" data-action="${cloud?.user?'signout':cloud?'auth':'firebase'}">${cloud?.user?'Sign out':cloud?'Sign in / Create account':'Connect Firebase'}</button>${cloud?'<button class="text-button" data-action="firebase">Project settings</button>':''}</div><p class="soft-text" style="margin-top:17px">Cloud sync uses the latest saved version. Avoid editing the same account on two devices at the same time.</p></section><section class="panel"><h2>Your data belongs to you</h2><p>Keep a copy of your progress or bring it to a new device.</p><div class="setting-row"><div><strong>Export your Bloom backup</strong><small>Includes tasks, rewards, and your growth history.</small></div><button class="secondary" data-action="export">Export</button></div><div class="setting-row"><div><strong>Restore a backup</strong><small>Replaces the current data on this device.</small></div><button class="secondary" data-action="import">Import</button><input id="import-file" type="file" accept="application/json,.json" hidden></div><div class="setting-row"><div><strong>A fresh start</strong><small>Clear tasks, rewards, and progress from this device${cloud?.user?' and the connected account':''}.</small></div><button class="text-button danger" data-action="reset">Reset</button></div></section></div>`;}
function openModal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
const modalHead=(title,sub='')=>`<div class="modal-heading"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${sub?`<p class="modal-subtitle">${sub}</p>`:''}`;
function taskModal(id){const t=state.tasks.find(t=>t.id===id);openModal(modalHead(t?'Make it yours':'One small intention','Choose something doable. Give yourself a reason to start.')+`<form id="task-form" data-id="${esc(id||'')}"><label class="field"><span>What would you like to do?</span><input name="title" maxlength="140" required placeholder="e.g. Work on my idea for 20 minutes" value="${esc(t?.title||'')}" autofocus></label><div class="field-row"><label class="field"><span>A little part of your life</span><select name="category">${['Personal','Work','Wellbeing','Learning','Home'].map(c=>`<option ${t?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field"><span>Time to make for it</span><input type="number" name="minutes" value="${t?.minutes||15}" min="1" max="480" required></label></div><div class="field-row"><label class="field"><span>How much effort?</span><select name="effort" ${t?.done?'disabled':''}>${[['easy','A small step · 20 pts'],['medium','A little stretch · 40 pts'],['hard','A big intention · 60 pts']].map(([e,l])=>`<option value="${e}" ${t?.effort===e?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Remind me at <small style="display:inline">(optional)</small></span><input name="reminder" type="time" value="${esc(t?.reminder||'')}"></label></div><label class="field"><span>When I finish, I get to…</span><input name="reward" maxlength="100" placeholder="Enjoy a tea break, watch a video…" value="${esc(t?.reward||'')}"><small>A personal celebration, free to enjoy when you finish. Points also go toward your bigger rewards.</small></label><div class="form-actions">${t?`<button class="text-button danger" type="button" data-action="delete-task" data-id="${esc(t.id)}">Delete task</button>`:''}<button class="secondary" type="button" data-action="close">Cancel</button><button class="primary" type="submit">${t?'Save changes':'Add to today'}</button></div></form>`);}
function rewardModal(id){const r=state.rewards.find(r=>r.id===id);openModal(modalHead(r?'A reward, reimagined':'Something to look forward to','Choose a little joy that makes you want to show up.')+`<form id="reward-form" data-id="${esc(id||'')}"><label class="field"><span>Your little reward</span><input name="title" maxlength="80" required placeholder="A trip to my favorite bookstore" value="${esc(r?.title||'')}" autofocus></label><div class="field-row"><label class="field"><span>A little personality</span><select name="emoji">${['☕','🍿','🎁','📚','🍰','🎮','🌿','🛁','🎨','🎵','🍦','🧋'].map(e=>`<option ${r?.emoji===e?'selected':''}>${e}</option>`).join('')}</select></label><label class="field"><span>Points to unlock</span><input name="cost" type="number" min="10" max="100000" step="10" required value="${r?.cost||60}"></label></div><p class="modal-subtitle">A small task earns 20 points, a medium one 40, and a big one 60. Choose a target that feels motivating.</p><div class="form-actions">${r?`<button class="text-button danger" type="button" data-action="delete-reward" data-id="${esc(r.id)}">Delete reward</button>`:''}<button class="secondary" type="button" data-action="close">Cancel</button><button class="primary" type="submit">${r?'Save changes':'Create reward'}</button></div></form>`);}
function focusModal(id){if(id&&!timer.running){const t=state.tasks.find(t=>t.id===id);timer.taskId=id;timer.duration=Math.min(25,t.minutes)*60;timer.remaining=timer.duration;}const t=state.tasks.find(t=>t.id===timer.taskId);openModal(modalHead('Just this moment','You don’t have to finish everything. Just give this moment a try.')+`<div class="timer-options"><button class="secondary ${timer.duration===1500?'active':''}" data-action="timer-duration" data-value="25">25-minute focus</button><button class="secondary ${timer.duration===300?'active':''}" data-action="timer-duration" data-value="5">5-minute start</button></div><div class="timer-face" id="timer-display">${timerText()}</div><p class="timer-label">${t?esc(t.title):'A little space for one thing that matters.'}</p><div class="timer-controls"><button class="primary" data-action="timer-toggle" id="timer-toggle">${timer.running?'Pause for a moment':'Let’s begin'}</button><button class="secondary" data-action="timer-reset">Reset</button></div><p class="modal-subtitle" style="text-align:center;margin-top:20px">You can close this window. The timer keeps going while Bloom is open.</p>`);}
function timerText(){return `${String(Math.floor(timer.remaining/60)).padStart(2,'0')}:${String(timer.remaining%60).padStart(2,'0')}`;}
function confirmModal(title,sub,action,id){openModal(modalHead(title,sub)+`<div class="form-actions"><button class="secondary" data-action="close">Keep it</button><button class="primary" data-action="${action}" data-id="${esc(id||'')}">Yes, continue</button></div>`);}
function install(){if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(c=>{if(c.outcome==='accepted')toast('A little growth, right on your home screen.');deferredInstall=null;});return;}openModal(modalHead('A little space on your home screen','Keep your daily intentions just a tap away.')+`<div class="install-steps"><strong>On iPhone or iPad</strong><br>Open in Safari → Share → Add to Home Screen.<br><br><strong>On Android</strong><br>Open in Chrome → Menu → Install app.<br><br><strong>On your computer</strong><br>Use the install icon in Chrome or Edge’s address bar.</div><p class="soft-text">Installation depends on your browser. Open the published app in your normal browser if this preview doesn’t offer installation.</p><div class="form-actions"><button class="primary" data-action="close">Got it</button></div>`);}
function firebaseModal(){let config={};try{config=JSON.parse(localStorage.getItem('bloom-firebase')||'{}');}catch{}openModal(modalHead('Connect your Firebase','Use your Firebase web app’s public configuration. Never paste a service account or private key.')+`<form id="firebase-form"><label class="field"><span>Firebase web configuration (JSON)</span><textarea name="config" rows="7" required placeholder='{"apiKey":"…","authDomain":"…","projectId":"…","messagingSenderId":"…","appId":"…"}'>${config.projectId?esc(JSON.stringify(config,null,2)):''}</textarea><small>In Firebase: Project settings → Your apps → Web app → Config. Enable Email/Password sign-in and deploy the included Firestore rules.</small></label><label class="field"><span>Web Push public VAPID key (optional)</span><input name="vapid" value="${esc(localStorage.getItem('bloom-vapid')||'')}" placeholder="For Firebase Cloud Messaging"><small>Deploy the included scheduled Firebase function to send task reminders when the app is closed.</small></label><div id="firebase-error" class="error-message" role="alert"></div><div class="form-actions"><button class="secondary" type="button" data-action="close">Later</button><button class="primary" type="submit">Connect project</button></div></form>`);}
function authModal(){openModal(modalHead('Bring your progress along','Sign in on your devices to keep your little wins together.')+`<form id="auth-form"><label class="field"><span>Email address</span><input name="email" type="email" required autocomplete="email"></label><label class="field"><span>Password</span><input name="password" type="password" required minlength="8" autocomplete="current-password"><small>Use at least 8 characters when creating an account.</small></label><div id="auth-error" class="error-message" role="alert"></div><div class="form-actions"><button class="secondary" name="mode" value="create" type="submit">Create account</button><button class="primary" name="mode" value="signin" type="submit">Sign in</button></div><button class="text-button" type="button" data-action="reset-password" style="margin-top:15px">Forgot your password?</button></form>`);}
function setCloudStatus(s){cloudStatus=s;$('#sync-label').textContent=s;}
async function initCloud(){const raw=localStorage.getItem('bloom-firebase');if(!raw)return;if(cloud?.dispose)cloud.dispose();setCloudStatus('Connecting…');try{const {connectFirebase}=await import('./firebase.js');cloud=await connectFirebase(JSON.parse(raw),async(user)=>{if(!user){setCloudStatus('Device mode');render();return;}setCloudStatus('Loading your space…');try{const remote=await cloud.loadState();if(remote){if(unsynced){openModal(modalHead('Two little spaces to bring together','This device has changes and your account already has cloud data. Choose which version to keep; both choices replace the other version.')+`<div class="form-actions"><button class="secondary" data-action="use-cloud">Use cloud data</button><button class="primary" data-action="use-device">Keep this device’s data</button></div>`);cloud.pendingState=remote;return;}state=validateState(remote);save({sync:false});}else{await cloud.saveState(state);unsynced=false;localStorage.setItem('bloom-dirty','false');}setCloudStatus('Synced');cloudError='';render();}catch(e){cloudError='Cloud sync could not load. Check your project, sign-in provider, and Firestore rules.';setCloudStatus('Sync paused');render();}});setCloudStatus(cloud.user?'Synced':'Sign in to sync');render();}catch(e){cloudError='Could not connect. Check the public configuration and your internet connection.';setCloudStatus('Device mode');render();throw e;}}
async function notify(title,body){if(!('Notification'in window)||Notification.permission!=='granted'){toast('Allow notifications in Settings to get device nudges.');return false;}if('serviceWorker'in navigator){try{const reg=await navigator.serviceWorker.ready;await reg.showNotification(title,{body,icon:'/icon-192.png',badge:'/icon-192.png',tag:'bloom-nudge',data:{url:location.origin}});return true;}catch{}}try{new Notification(title,{body,icon:'/icon-192.png'});return true;}catch{toast('This browser needs Bloom installed to show notifications.');return false;}}
async function enableNotifications(){if(state.settings.notifications){state.settings.notifications=false;save();render();toast('Gentle nudges paused.');return;}if(!('Notification'in window)){toast('Notifications aren’t supported in this browser. Try the installed app.');return;}const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Notifications aren’t enabled. You can allow them in browser settings.');return;}state.settings.notifications=true;save();render();await notify('A little hello from Bloom 🌿','Your next small step is waiting. You’ve got this.');if(cloud?.user&&localStorage.getItem('bloom-vapid')){try{await cloud.enableMessaging(localStorage.getItem('bloom-vapid'));toast('Firebase push is ready on this device.');}catch{toast('Device nudges work. Check Firebase Cloud Messaging setup for background push.');}}}
const actions={
'close':()=>$('#modal').close(),'goto':el=>{location.hash=el.dataset.value;},'filter':el=>{filter=el.dataset.value;render();},'add-task':()=>taskModal(),'edit-task':el=>taskModal(el.dataset.id),'add-reward':()=>rewardModal(),'edit-reward':el=>rewardModal(el.dataset.id),'install':install,'firebase':firebaseModal,'auth':authModal,'focus':el=>focusModal(el.dataset.id),'notifications':enableNotifications,'test-notification':()=>notify('Your next little win is waiting 🌱','Pick one small thing. A few minutes is enough to begin.'),'complete':el=>{try{const t=completeTask(state,el.dataset.id);state.starter=false;save();render();if(t.done){celebrate();toast(`+${t.points} points! ${t.reward?`Enjoy: ${t.reward}`:'A little promise kept. Well done.'}`);}else toast('Task moved back to your intentions.');}catch(e){toast(e.message);}},
'delete-task':el=>{const t=state.tasks.find(t=>t.id===el.dataset.id);if(t.done){toast('Completed tasks keep your points history intact. You can edit the title.');return;}confirmModal('Let this intention go?','Sometimes making space is a good thing. This removes the task.','confirm-delete-task',t.id);},'confirm-delete-task':el=>{state.tasks=state.tasks.filter(t=>t.id!==el.dataset.id);state.starter=false;save();$('#modal').close();render();toast('A little more space in your day.');},'delete-reward':el=>confirmModal('Remove this reward?','Your past reward moments will stay in your history.','confirm-delete-reward',el.dataset.id),'confirm-delete-reward':el=>{state.rewards=state.rewards.filter(r=>r.id!==el.dataset.id);save();$('#modal').close();render();},
'claim':el=>{const r=state.rewards.find(r=>r.id===el.dataset.id);if(balance(state)<r.cost)return;openModal(modalHead('You’ve earned a little joy',`Enjoy ${esc(r.title)} for ${r.cost} points? This adds the reward to your history.`)+`<span class="reward-emoji">${esc(r.emoji)}</span><div class="form-actions"><button class="secondary" data-action="close">Save for later</button><button class="primary" data-action="confirm-claim" data-id="${esc(r.id)}">This one’s for me</button></div>`);},'confirm-claim':el=>{try{const c=claimReward(state,el.dataset.id);save();$('#modal').close();render();celebrate();toast(`Enjoy ${c.title.toLowerCase()}. You earned it!`);}catch(e){toast(e.message);}},
'carry':()=>{const pending=state.tasks.filter(t=>!t.done&&t.date<dayKey());pending.forEach(t=>{t.date=dayKey();t.reminder='';});save();render();toast(`${pending.length} intentions brought into today. A fresh chance.`);},
'timer-duration':el=>{if(timer.running){toast('Pause the timer before changing its length.');return;}timer.duration=Number(el.dataset.value)*60;timer.remaining=timer.duration;focusModal();},'timer-toggle':()=>{if(timer.remaining<=0)timer.remaining=timer.duration;timer.running=!timer.running;if(timer.running)timer.end=Date.now()+timer.remaining*1000;$('#timer-toggle').textContent=timer.running?'Pause for a moment':'Let’s begin';render();},'timer-reset':()=>{timer.running=false;timer.remaining=timer.duration;focusModal();render();},
'export':()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`bloom-backup-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('A copy of your little wins, saved.');},'import':()=>$('#import-file').click(),'reset':()=>confirmModal('Begin with a clear space?','This permanently clears your tasks, rewards, points, and growth history. Export a backup first if you want to keep them.','confirm-reset'),'confirm-reset':()=>{const settings=state.settings;state=createState();state.tasks=[];state.starter=false;state.settings=settings;save();$('#modal').close();render();toast('A fresh little beginning.');},
'signout':async()=>{if(unsynced||cloudBusy){toast('Let your changes finish syncing before signing out.');return;}await cloud.signOut();toast('Signed out. Your data remains saved on this device.');},'use-cloud':()=>{try{state=validateState(cloud.pendingState);unsynced=false;localStorage.setItem('bloom-dirty','false');save({sync:false});delete cloud.pendingState;setCloudStatus('Synced');$('#modal').close();render();}catch{toast('The cloud data could not be read. Keep your device data instead.');}},'use-device':()=>{delete cloud.pendingState;$('#modal').close();save();render();},'reset-password':async()=>{const input=$('#auth-form input[name="email"]');if(!input.value||!input.checkValidity()){input.reportValidity();return;}try{await cloud.resetPassword(input.value);toast('If an account exists, you’ll receive a password reset email.');}catch{toast('Could not request a reset. Check the address and try again.');}}
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=actions[el.dataset.action];if(!action)return;try{await action(el);}catch{toast('Something didn’t finish. Please try again.');}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['task-form','reward-form','profile-form','firebase-form','auth-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),id=form.dataset.id;
if(form.id==='task-form'){const title=data.title.trim();if(!title)return;const existing=state.tasks.find(t=>t.id===id);const effort=existing?.done?existing.effort:data.effort;const t={id:id||uid(),date:existing?.date||dayKey(),done:existing?.done||false,completedAt:existing?.completedAt||null,title,category:data.category,minutes:Number(data.minutes),effort,points:pointsFor(effort),reward:data.reward.trim(),reminder:data.reminder};if(existing)Object.assign(existing,t);else state.tasks.push(t);state.starter=false;save();$('#modal').close();render();toast(existing?'A little adjustment. You’re ready.':'One small intention, ready for today.');}
if(form.id==='reward-form'){const title=data.title.trim();if(!title)return;const r={id:id||uid(),title,emoji:data.emoji,cost:Number(data.cost)};const existing=state.rewards.find(r=>r.id===id);if(existing)Object.assign(existing,r);else state.rewards.push(r);save();$('#modal').close();render();toast('Something lovely to look forward to.');}
if(form.id==='profile-form'){state.settings.name=data.name.trim();save();render();toast('Your space, a little more you.');}
if(form.id==='firebase-form'){const button=form.querySelector('[type="submit"]');button.disabled=true;try{const c=JSON.parse(data.config);if(c.private_key||c.type==='service_account')throw Error('Use the public web app configuration, never a service account.');if(!['apiKey','authDomain','projectId','appId','messagingSenderId'].every(k=>typeof c[k]==='string'&&c[k].trim()))throw Error('Please include apiKey, authDomain, projectId, appId, and messagingSenderId.');const sanitized=Object.fromEntries(['apiKey','authDomain','projectId','appId','messagingSenderId','storageBucket'].filter(k=>c[k]).map(k=>[k,c[k]]));localStorage.setItem('bloom-firebase',JSON.stringify(sanitized));localStorage.setItem('bloom-vapid',data.vapid.trim());await initCloud();$('#modal').close();authModal();}catch(err){if($('#firebase-error'))$('#firebase-error').textContent=err.message||'Could not connect to Firebase.';}finally{button.disabled=false;}}
if(form.id==='auth-form'){const buttons=form.querySelectorAll('[type="submit"]');buttons.forEach(b=>b.disabled=true);try{await cloud.authenticate(data.email,data.password,e.submitter?.value==='create');$('#modal').close();toast('Welcome to your little space.');}catch(err){if($('#auth-error'))$('#auth-error').textContent='Could not sign in. Check your email and password, or check that Email/Password sign-in and this domain are enabled in Firebase.';}finally{buttons.forEach(b=>b.disabled=false);}}
});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;if(file.size>5000000){toast('Please choose a Bloom backup smaller than 5 MB.');return;}try{window.importedBloom=validateState(JSON.parse(await file.text()));openModal(modalHead('Bring this little space back?',`This backup has ${window.importedBloom.tasks.length} tasks and ${window.importedBloom.claims.length} reward moments. Importing replaces your current progress.`)+`<div class="form-actions"><button class="secondary" data-action="close">Cancel</button><button class="primary" data-action="confirm-import">Restore backup</button></div>`);}catch(err){toast(err.message||'This backup couldn’t be read.');}e.target.value='';});
actions['confirm-import']=()=>{state=validateState(window.importedBloom);delete window.importedBloom;save();$('#modal').close();render();toast('Your little wins are back where they belong.');};
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(names[next]){page=next;render();window.scrollTo({top:0,behavior:'instant'});}});
$('#profile-button').onclick=$('#account-button').onclick=()=>location.hash='settings';$('#notification-button').onclick=()=>location.hash='settings';$('#install-side').onclick=install;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});window.addEventListener('appinstalled',()=>{deferredInstall=null;toast('Welcome home, Bloom. 🌿');});
setInterval(()=>{if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if($('#timer-display'))$('#timer-display').textContent=timerText();if(!timer.remaining){timer.running=false;state.focusSessions.push({id:uid(),minutes:Math.round(timer.duration/60),completedAt:new Date().toISOString(),taskId:timer.taskId});save();if($('#timer-toggle'))$('#timer-toggle').textContent='Begin again';toast('A little focus, a real step forward. Take a well-earned breath.');if(state.settings.notifications)notify('You showed up. That counts. 🌿','Your focus session is complete. Take a well-earned breath.');celebrate();render();}}if(lastDay!==dayKey()){lastDay=dayKey();filter='all';render();}},1000);
async function checkReminders(){if(!state.settings.notifications)return;const now=new Date(),time=now.toTimeString().slice(0,5);for(const t of todayTasks().filter(t=>!t.done&&t.reminder&&t.reminder<=time)){const when=new Date(`${t.date}T${t.reminder}`);if(now-when>10*60*1000)continue;const key=`bloom-reminder-${t.id}-${t.date}-${t.reminder}`;if(localStorage.getItem(key))continue;if(await notify('A gentle nudge from Bloom 🌱',t.title))localStorage.setItem(key,'sent');}}
setInterval(checkReminders,30000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){checkReminders();if(unsynced)queueSync();}});window.addEventListener('online',()=>{if(unsynced)queueSync();});
render();save({sync:false});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});initCloud().catch(()=>{});

if('serviceWorker' in navigator)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='BLOOM_PUSH')toast(e.data.body||'Your next little win is waiting.');});
